import{_ as e,o,c as s,a4 as a}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"共识","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/consensus/index.md","filePath":"distributed/consensus/README.md","lastUpdated":1788475713000}'),r={name:"distributed/consensus/index.md"};function i(n,t,l,p,d,u){return o(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="共识" tabindex="-1">共识 <a class="header-anchor" href="#共识" aria-label="Permalink to &quot;共识&quot;">​</a></h1><p>共识 (Consensus) 是分布式系统的&quot;原子核&quot; — <strong>让 N 个节点对一个值/序列达成一致 (agreement), 并且该相同决定 forever 不变 (validity / integrity / non-triviality), 同时保证非故障节点 eventually 决定 (termination)</strong>.</p><p>围绕 consensus 形式化的工程算法三巨:</p><ul><li><strong>Paxos / Multi-Paxos</strong>: Lamport 1989/1998, 是分布式共识数学上最通用语言。 难读, Google Chubby 把它跑生产实现。</li><li><strong>Raft</strong>: Ongaro-Ousterhout 2014, 同 crash-stop model 但 leader-log 形式 simple.</li><li><strong>ZAB</strong>: Yahoo! ZAB (ZooKeeper), &quot;Atomic Broadcast&quot; 是 total-order broadcast consensus.</li></ul><p>其他实践中:</p><ul><li><p><strong>HotStuff</strong> (VMware 2018): BFT-friendly pipeline blocks, 现代区块链一派 core.</p></li><li><p><strong>EPaxOS</strong>: leaderless, 通信 O(N) — 实际依赖 conflict-graph dependency。</p></li><li><p><strong>PBFT</strong>: 经典 BFT consensus。</p></li><li><p><a href="./paxos">Paxos / Multi-Paxos</a></p></li><li><p><a href="./raft">Raft 详解</a></p></li><li><p><a href="./linearizability">ZooKeeper / etcd / Linearizability</a></p></li></ul>',6)])])}const _=e(r,[["render",i]]);export{g as __pageData,_ as default};
